import heapq

def shortestPath(start, end):
    #build adjacency list
    graph = {}
    graph["start"] = {'neighbors': {}}
    for i in range(len(graph['start'])):
        if i < len(graph['start']):
            pass

    #adjacency list: start node is 0
    #graph[0] is a dictionary with keys as neighbor nodes and values as distances
    #edges are undirected

    def dijkstra(start, end):
        #initialize
        #distances = dictionary of node to shortest distance from start
        distances = {0:0}
        visited = set()
        heap = [(0,0)]

        while heap:
            current_dist, current_node = heapq.heappop(heap)
            if current_node == end:
                return current_dist
            if current_node in visited:
                continue
            visited.add(current_node)
            for neighbor, weight in graph[current_node].items():
                new_dist = current_dist + weight
                if neighbor not in distances or new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    heapq.heappush(heap, (new_dist, neighbor))

        return -1

    return dijkstra(start, end)

